```python
import unittest

class TestCalc(unittest.TestCase):
    def setUp(self):
        self.x = 10
        self.y = 20

    def test_sum(self):
        self.assertEqual(self.x + self.y, 30)

    def tearDown(self):
        self.x = 0
```

