import pytest

def calculate_area(radius):
    return 3.14159 * radius * radius

@pytest.mark.parametrize('radius, expected', [
    (1, 3.14159),
    (2, 12.56636),
    (10, 314.159),
    (5, 78.53975)
])
def test_area(radius, expected):
    assert calculate_area(radius) == expected
